const TARGET_FOOTPRINT = 20; // Set an ideal daily carbon goal

const calculateProgress = (footprint) => {
  return Math.round(100 * Math.max(TARGET_FOOTPRINT - footprint, 0) / (TARGET_FOOTPRINT + footprint));
};

export const calculateCarbonMetrics = (userData) => {
  console.log("Received userData:", userData);

  const emissionFactors = {
    electricity: 0.43, // kg CO₂ per kWh
    naturalGas: 2.2, // kg CO₂ per therm
    vehicleMiles: 0.2, // kg CO₂ per mile (average)
    airTravel: 0.25, // kg CO₂ per mile (higher impact)
    wasteProduced: 0.1, // kg CO₂ per kg waste
    recycling: -0.5 // Recycling saves emissions!
  };

  const footprint =
    (userData.electricity || 0) * emissionFactors.electricity +
    (userData.naturalGas || 0) * emissionFactors.naturalGas +
    (userData.vehicleMiles || 0) * emissionFactors.vehicleMiles +
    (userData.airTravel || 0) * emissionFactors.airTravel +
    (userData.wasteProduced || 0) * emissionFactors.wasteProduced +
    (userData.recycling || 0) * emissionFactors.recycling; // ✅ Recycling impact

  console.log("Calculated footprint:", footprint);

  const progress = calculateProgress(footprint);

  // Reward system: More credits for staying under the target
  const credits = footprint <= TARGET_FOOTPRINT
    ? Math.round((1 - footprint / TARGET_FOOTPRINT) * 10)
    : 0; // No credits if above target

  const rank = Math.floor(Math.random() * 100);

  const result = {
    totalCarbon: parseFloat(footprint.toFixed(1)),
    credits,
    progress,
    rank
  };

  console.log("Final calculated metrics:", result);
  return result;
};
